-- Store, catalogue, delivery, customers, conversations and orders.
create table public.store_settings (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), display_name text not null, legal_name text default '', cnpj text default '', whatsapp text default '', phone text default '', email text default '', logo_path text, postal_code text default '', street text default '', number text default '', complement text default '', neighborhood text default '', city text default '', state text default '', latitude numeric, longitude numeric, minimum_order_cents integer not null default 0 check(minimum_order_cents>=0), preparation_minutes integer not null default 40 check(preparation_minutes between 5 and 300), delivery_enabled boolean not null default true, pickup_enabled boolean not null default true, status_mode text not null default 'automatic' check(status_mode in ('automatic','forced_open','forced_closed')), welcome_message text not null default '', closed_message text not null default '', additional_information text not null default '', currency text not null default 'BRL', timezone text not null default 'America/Sao_Paulo', time_format text not null default '24h', check(delivery_enabled or pickup_enabled), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id));
create index store_settings_tenant_created on public.store_settings(tenant_id,created_at desc);
create trigger touch_store_settings before update on public.store_settings for each row execute function private.touch_updated_at();
create table public.store_business_hours (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), day_of_week integer not null check(day_of_week between 0 and 6), start_time time not null, end_time time not null, check(start_time<>end_time), sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id));
create index store_business_hours_tenant_created on public.store_business_hours(tenant_id,created_at desc);
create trigger touch_store_business_hours before update on public.store_business_hours for each row execute function private.touch_updated_at();
create table public.menu_categories (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), name text not null, description text not null default '', image_path text, active boolean not null default true, sort_order integer not null default 0, allow_split boolean not null default false, split_pricing text not null default 'highest' check(split_pricing in ('highest','proportional')), archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id));
create index menu_categories_tenant_created on public.menu_categories(tenant_id,created_at desc);
create trigger touch_menu_categories before update on public.menu_categories for each row execute function private.touch_updated_at();
create table public.menu_sizes (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), category_id uuid not null, foreign key(tenant_id,category_id) references public.menu_categories(tenant_id,id), name text not null, slices integer check(slices between 1 and 24), max_flavors integer not null default 1 check(max_flavors between 1 and 2), active boolean not null default true, sort_order integer not null default 0, archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id));
create index menu_sizes_tenant_created on public.menu_sizes(tenant_id,created_at desc);
create trigger touch_menu_sizes before update on public.menu_sizes for each row execute function private.touch_updated_at();
