create table public.menu_borders (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), name text not null, base_price_cents integer not null default 0 check(base_price_cents>=0), active boolean not null default true, archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id));
