create table public.notification_preferences (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), user_id uuid not null references public.profiles(id), sound_enabled boolean not null default false, push_enabled boolean not null default false, orders_enabled boolean not null default true, messages_enabled boolean not null default true, whatsapp_enabled boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,user_id));
create index notification_preferences_tenant_created on public.notification_preferences(tenant_id,created_at desc);
create trigger touch_notification_preferences before update on public.notification_preferences for each row execute function private.touch_updated_at();
create table public.team_invites (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), email text not null, role text not null check(role in ('admin','manager','attendant','kitchen','custom')), token_hash text not null unique, invited_by uuid not null references public.profiles(id), status text not null default 'pending', expires_at timestamptz not null default now()+interval '7 days', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id));
create index team_invites_tenant_created on public.team_invites(tenant_id,created_at desc);
create trigger touch_team_invites before update on public.team_invites for each row execute function private.touch_updated_at();
create unique index one_active_whatsapp on public.whatsapp_instances(tenant_id) where archived_at is null;
create unique index one_active_cart on public.carts(tenant_id,conversation_id) where status='active';
create unique index one_default_address on public.customer_addresses(tenant_id,customer_id) where is_default and active and archived_at is null;
create unique index standard_payment_method on public.payment_methods(tenant_id,type) where type<>'custom_manual' and archived_at is null;
create index orders_status_created on public.orders(tenant_id,order_status,created_at desc);
create index conversations_recent on public.conversations(tenant_id,last_message_at desc);
create index messages_conversation_created on public.conversation_messages(tenant_id,conversation_id,created_at desc,id);
create index orders_customer on public.orders(tenant_id,customer_id,created_at desc);
create index notifications_unread on public.notifications(tenant_id,user_id,created_at desc) where read_at is null;
create function private.initialize_store() returns trigger language plpgsql security definer set search_path='' as $$ begin
 insert into public.store_settings(tenant_id,display_name) values(new.id,new.name);
 insert into public.delivery_settings(tenant_id) values(new.id);
 insert into public.print_settings(tenant_id) values(new.id);
 insert into public.payment_methods(tenant_id,type,name,active) values(new.id,'cash','Dinheiro',true),(new.id,'credit_on_delivery','Crédito na entrega',false),(new.id,'debit_on_delivery','Débito na entrega',false),(new.id,'pix_manual','PIX manual',false),(new.id,'pix_mercado_pago','PIX Mercado Pago',false);
 return new;
end $$;
create trigger initialize_store after insert on public.tenants for each row execute function private.initialize_store();
